function getFactors(n) {
  const result = [];
  const path = [];

  function backtrack(remaining, start) {
    for (let factor = start; factor * factor <= remaining; factor++) {
      if (remaining % factor !== 0) {
        continue;
      }
      path.push(factor);
      result.push([...path, remaining / factor]);
      backtrack(remaining / factor, factor);
      path.pop();
    }
  }

  backtrack(n, 2);
  return result;
}

