function getFactors(n) {
  // Build every sorted factorization of each divisor d of n from the smaller divisors, removing repeats with a map.
  const divisors = [];
  for (let d = 1; d * d <= n; d++) {
    if (n % d === 0) {
      divisors.push(d);
      if (d * d !== n) divisors.push(n / d);
    }
  }
  divisors.sort((a, b) => a - b);
  const ways = new Map();
  for (const d of divisors) {
    if (d === 1) continue;
    const unique = new Map([[String(d), [d]]]);
    for (const f of divisors) {
      if (f < 2 || f >= d || d % f !== 0) continue;
      for (const rest of ways.get(d / f)) {
        const combo = [f, ...rest].sort((a, b) => a - b);
        unique.set(combo.join(','), combo);
      }
    }
    ways.set(d, [...unique.values()]);
  }
  return n === 1 ? [] : ways.get(n).filter(combo => combo.length > 1);
}

