function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    // Mostly random values near the limit, sometimes a product of small primes with many factorizations.
    if (rand() < 0.5) return [9000000 + pick(1000001)];
    // The output must stay small, so products with too many factorizations are drawn again.
    const count = (remaining, start) => { let c = 0; for (let f = start; f * f <= remaining; f++) if (remaining % f === 0) c += 1 + count(remaining / f, f); return c; };
    const primes = [2, 2, 2, 3, 3, 5, 7, 11, 13];
    for (;;) {
      let n = 1;
      for (let p = primes[pick(primes.length)]; n * p <= 10000000; p = primes[pick(primes.length)]) n *= p;
      if (count(n, 2) <= 5000) return [n];
    }
  }
  const roll = rand();
  if (roll < 0.15) return [1 + pick(3)];
  if (roll < 0.35) return [2 ** pick(11)];
  if (roll < 0.6) {
    let n = 1;
    const factors = 1 + pick(5);
    for (let i = 0; i < factors; i++) n *= [2, 3, 5, 7][pick(4)];
    return [n];
  }
  return [1 + pick(1000)];
}
